import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError("File not found")
    def run_script():
        try:
            subprocess.run(['python', script_path], check=True, timeout=timeout)
            result.append("Script executed successfully.")
        except subprocess.TimeoutExpired:
            result.append("Terminating process due to timeout.")
    result = []
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout + 1)
    if thread.is_alive():
        return "Terminating process due to timeout."
    return result[0]

import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError("File not found")
    def run_script():
        process = subprocess.Popen(['python', script_path])
        process.wait()
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

